// Define an interval with a lower and upper bound.
#[derive(Debug, Clone, PartialEq)]
pub struct Interval {
    pub min: f64,
    pub max: f64,
}

impl Interval {
    /// Create a new interval, panicking if min >= max.
    pub fn new(min: f64, max: f64) -> Self {
        assert!(min < max, "Interval lower bound must be less than upper bound");
        Interval { min, max }
    }
}

/// Descriptor for a Chebyshev polynomial:
/// - `coeffs` are the polynomial coefficients (from degree 0 upwards), as i32.
/// - `domain` is the interval on which the Chebyshev approximation is defined.
/// - `window` is the output window interval.
#[derive(Debug, Clone, PartialEq)]
pub struct ChebyshevPoly {
    pub coeffs: Vec<i32>,
    pub domain: Interval,
    pub window: Interval,
}

/// Construct a Chebyshev polynomial descriptor from an input vector of i8 coefficients.
/// 
/// The input vector must be non-empty.  The returned descriptor converts each coefficient
/// to i32, and sets both the domain and window to the default interval [-1.0, 1.0].
/// Panics if the input vector is empty or if the intervals would be invalid.
pub fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    // The problem statement assumes the input list is non-empty.
    assert!(!coef.is_empty(), "Coefficient list must be non-empty");

    // Convert i8 coefficients to i32, preserving order.
    let coeffs: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    // Default domain and window intervals are [-1, 1].
    let domain = Interval::new(-1.0, 1.0);
    let window = Interval::new(-1.0, 1.0);

    ChebyshevPoly {
        coeffs,
        domain,
        window,
    }
}

